$corePath = $modx->getOption('core_path', '', MODX_CORE_PATH);
switch ($modx->event->name) {
    case 'msOnBeforeCreateOrder':
        /**
         * @var msOrder $msOrder
         */
        $address = $msOrder->getOne('Address');
        $properties = $address->get('properties') ?: [];
        $deliveryStatus = $_SESSION['mscdek2']['data'] ?? [];
        $deliveryStatus['point'] = strip_tags($_POST['point']);
        $properties = array_merge($properties, $deliveryStatus);
        $address->set('properties', $properties);
        $address->save();
        unset($_SESSION['mscdek2']);
        break;
    case 'msOnManagerCustomCssJs':
        /**
         * @var string $page
         */
        if ($page != 'orders') {
            return;
        }
        $modx->controller->addLastJavascript(MODX_ASSETS_URL . 'components/ms_cdek2/js/mgr/orders/orders.window.js');
        break;

    case 'OnLoadWebDocument':
        require_once $corePath . 'components/ms_cdek2/services/vendor/autoload.php';

        $object = new MsCdek2Services\MsCdek2($modx);
        $object->loadJSCSS($modx->resource->template);
        break;
    case 'OnGetFormParams':
        require_once $corePath . 'components/ms_cdek2/services/vendor/autoload.php';
        /**
         * @var string $presetName
         * @var \SendIt $SendIt
         */
        $object = new MsCdek2Services\MsCdek2($modx);
        $params = $object->setSendItParams($presetName);
        if (!empty($params)) {
            $SendIt->pluginParams = $params;
        }
        break;

    case 'OnCacheUpdate':
        require_once $corePath . 'components/ms_cdek2/services/vendor/autoload.php';
        $object = new MsCdek2Services\MsCdek2($modx);
        $object->cleanCache();
        break;

    case 'msOnBeforeGetOrderCost':
        require_once $corePath . 'components/ms_cdek2/services/vendor/autoload.php';
        $object = new MsCdek2Services\MsCdek2($modx);
        $object->resetStatus();
        break;
}

